    }

    /// Main only, never from the queue: `body` on the store's queue, so a
    /// file act of the app's (`removeModule`, `moveModule`) never interleaves
    /// with a pass.
    func onQueue<T>(_ body: () throws -> T) rethrows -> T {
        try queue.sync(execute: body)
