    stackedViews.append(content)
    let stack = NSStackView(views: stackedViews)
    stack.orientation = .vertical
    stack.alignment = .leading
    stack.spacing = 12
    stack.setCustomSpacing(16, after: stackedViews[stackedViews.count - 2])

    stack.translatesAutoresizingMaskIntoConstraints = false
    buttonRow.translatesAutoresizingMaskIntoConstraints = false
    container.addSubview(stack)
    container.addSubview(buttonRow)
    NSLayoutConstraint.activate([
        container.widthAnchor.constraint(equalToConstant: width),
        stack.topAnchor.constraint(equalTo: container.topAnchor, constant: sheetInset),
        stack.leadingAnchor.constraint(equalTo: container.leadingAnchor, constant: sheetInset),
        stack.trailingAnchor.constraint(
            lessThanOrEqualTo: container.trailingAnchor, constant: -sheetInset),
        buttonRow.topAnchor.constraint(equalTo: stack.bottomAnchor, constant: sheetInset),
        buttonRow.leadingAnchor.constraint(equalTo: container.leadingAnchor, constant: sheetInset),
        buttonRow.trailingAnchor.constraint(equalTo: container.trailingAnchor, constant: -sheetInset),
        buttonRow.bottomAnchor.constraint(equalTo: container.bottomAnchor, constant: -sheetInset),
    ])
    return container
}

/// The sheet's button row: `leading` at the far left (a footnote), then a
/// spacer, then the trailing cluster.
///
/// **`secondary` is a second affirmative button**, left of Cancel and inside
/// the trailing cluster — a "do something else with this card" beside the
/// button that does the main thing. It is NOT `leading`, which is where the
/// footnote lives: an affirmative button at the far left of a dialog reads as
/// a destructive or a tertiary one, and on most sheets it would sit under a
/// footnote besides. It takes no key equivalent, which is the other half
/// of the same point — Return belongs to `apply` and Escape to `cancel`, and a
/// row with two Returns has none.
///
/// Its one caller is the export sheet's "Add to Queue" (road map 2's phase 7e,
/// built and passed in `ExportSheetController.loadView`) — the shipped example
/// to read before a second dialog takes the slot. The parameter landed a wave
/// AHEAD of that button, alone, because this file is shared by every dialog in
/// the app and a change to it is worth making where the type checker can see
/// every existing call is unchanged; it defaults to nil, so every dialog but
/// the export card still asks for the two-button row it always had.
///
/// **Every `leading` view resists compression at `.defaultLow`**, below the
/// buttons' default 750, so a long footnote gives way before a button and the
/// row has one answer instead of two tied ones (#141; a divergence from
/// Rasterize's copy).
func makeButtonRow(
    cancel: NSButton, apply: NSButton, secondary: NSButton? = nil, leading: [NSView] = []
) -> NSStackView {
    cancel.keyEquivalent = "\u{1b}"
    apply.keyEquivalent = "\r"
    for view in leading {
        view.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
    }
    let spacer = NSView()
    spacer.setContentHuggingPriority(.defaultLow - 1, for: .horizontal)
    let trailing: [NSView] = secondary.map { [$0, cancel, apply] } ?? [cancel, apply]
    let row = NSStackView(views: leading + [spacer] + trailing)
    row.orientation = .horizontal
    row.alignment = .centerY
    row.spacing = 8
    return row
}

/// 13px row label for the sheet grids' 106px right-aligned label column.
func fieldLabel(_ text: String) -> NSTextField {
    let label = NSTextField(labelWithString: text)
    label.font = DS.sans(13)
    label.textColor = DS.textStrong
    return label
}

/// 10px mono footnote: in the button row's `leading` slot, or on a line of
/// its own under a sheet's content (the export sheet, #243). A label built by
/// `NSTextField(labelWithString:)` breaks by clipping, so a footnote too long
/// for its room ends with a tail ellipsis and carries the whole string as a
/// tooltip (Rasterize's two lines, #141).
func sheetFootnote(_ text: String) -> NSTextField {
    let label = NSTextField(labelWithString: text)
    label.font = DS.mono(10)
    label.textColor = DS.textFaint
    label.lineBreakMode = .byTruncatingTail
    label.toolTip = text
    return label
}

func sheetCancelButton(target: AnyObject, action: Selector) -> NSButton {
    StickerButton(title: "Cancel", style: .secondary, target: target, action: action)
}

func sheetApplyButton(target: AnyObject, action: Selector) -> NSButton {
    StickerButton(title: "Apply", style: .primary, target: target, action: action)
}

// MARK: - Frame Job's own pieces (not in Rasterize's copy)
//
// The progress sheets' chrome and the settings sheets' grid, once each, so a
// sheet is built from them rather than re-typing the metrics (#359).

/// A progress sheet's bar: determinate 0…1 unless `indeterminate`, as wide as
    grid.rowSpacing = 10
    grid.columnSpacing = 12
    grid.column(at: 0).xPlacement = .trailing
    grid.column(at: 0).width = 106
    return grid
}

/// A settings sheet's content column: its pieces stacked 10px apart.
func sheetColumn(_ views: [NSView]) -> NSStackView {
    let stack = NSStackView(views: views)
    stack.orientation = .vertical
    stack.alignment = .leading
    stack.spacing = 10
    return stack
}

/// The controls of one grid row, side by side, 6px apart.
func sheetRow(_ views: [NSView]) -> NSStackView {
    let row = NSStackView(views: views)
    row.orientation = .horizontal
    row.alignment = .centerY
    row.spacing = 6
    return row
}

/// The muted 13px unit after a field ("×", "s", "dB").
// app/Sources/GraphicCatalog.swift — what Insert ▸ Graphic… lists (spec §11
// G-45): the bundled templates and the project's own modules as categories
// of graphics, in the one order the sheet (`GraphicBrowserSheetController`)
// and `list_graphics` (`AgentServer+GraphicBrowser.swift`) both show.
//
// **A template is compiled to read its `meta`, once per process**
// (`GraphicTemplateLibrary`, G-45 (e)): its title is `meta.name`, its
// category `meta.category`, its description `meta.description`. The first
// read is on main, when the browser or the tool first asks; it compiles
// against a library of the bundled fonts alone and is memoised under a lock.
// The menu bar never reads it (chrome probes instantiate `AppDelegate()`).
//
// **A project module is read from the registry**: the document's compiled
// set, as the inspector and the op tools read it. A module that does not
// compile is still listed (`ok` false), titled from its stem, so a person
// can see it is there and read why it will not insert.

import Foundation

/// One graphic the browser lists.
struct GraphicBrowserItem: Equatable {
    enum Origin: String { case template, project }
    /// A template's file stem; a project module's name.
    let name: String
    /// `GraphicCatalog.title(meta:name:)`; a This Project duplicate carries
    /// " — <name>" (G-45 (e)).
    let title: String
    let description: String?
    /// The module's own category (`meta.category`, else "Other") — a This
    /// Project item keeps its own here though it is listed under This Project.
    let category: String
    let origin: Origin
    /// The module compiled.
    let ok: Bool
}

/// One category and its graphics, in order.
struct GraphicBrowserCategory: Equatable {
    let name: String
    let items: [GraphicBrowserItem]
}

enum GraphicCatalog {
    static let thisProject = "This Project", other = "Other"

    /// G-45 (a): `meta.category` trimmed when it is a non-empty string, else
    /// "Other".
    static func category(meta: [String: Any]) -> String {
        let named = (meta["category"] as? String)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return named.isEmpty ? other : named
    }

    /// G-45 (e): `meta.name` when it is a non-empty string, else the stem's
    /// title (`GraphicTemplates.title(for:)`).
    static func title(meta: [String: Any], name: String) -> String {
        let named = (meta["name"] as? String)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return named.isEmpty ? GraphicTemplates.title(for: name) : named
    }

    /// `meta.description` trimmed, nil when absent or blank.
    static func description(meta: [String: Any]) -> String? {
        let text = (meta["description"] as? String)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return text.isEmpty ? nil : text
    }

    /// One item from a compiled (or failed, or absent) registry entry.
    static func item(
        name: String, entry: GraphicRegistry.Entry?, origin: GraphicBrowserItem.Origin
    ) -> GraphicBrowserItem {
        var meta: [String: Any] = [:]
        var ok = false
        if case .compiled(_, _, let described, _)? = entry {
            meta = described
            ok = true
        }
        return GraphicBrowserItem(
            name: name, title: title(meta: meta, name: name), description: description(meta: meta),
            category: category(meta: meta), origin: origin, ok: ok)
    }

    /// G-45 (d): This Project first, only when `project` holds an item, with
    /// (e)'s duplicate titles told apart; then the templates' categories by
    /// case-insensitive name, Other last. Items by title case-insensitively,
    /// then by name.
    static func categories(
        templates: [GraphicBrowserItem], project: [GraphicBrowserItem]
    ) -> [GraphicBrowserCategory] {
        let ours: [GraphicBrowserCategory] = project.isEmpty ? []
            : [GraphicBrowserCategory(name: thisProject, items: sorted(distinguished(project)))]
        let names = Set(templates.map(\.category)).sorted { a, b in
            if (a == other) != (b == other) { return b == other }
            return a.caseInsensitiveCompare(b) == .orderedAscending
        }
        let theirs = names.map { name in
            GraphicBrowserCategory(
                name: name, items: sorted(templates.filter { $0.category == name }))
        }
        return ours + theirs
    }

    /// The document's list: the bundled templates and the modules its
    /// `graphics/` holds as the registry compiled them. Main.
    static func categories(for document: ProjectDocument) -> [GraphicBrowserCategory] {
        let templates = GraphicTemplateLibrary.shared.entries.map {
            item(name: $0.template.name, entry: $0.entry, origin: .template)
        }
        let modules = document.graphicStore?.scan.modules.keys.sorted() ?? []

