        return Err(format!(
            "files must be an array, not {}",
            shown(object.get("files"))
        ));
    };
    if list.is_empty() {
        return Err(format!(
            "files must begin with \"{module}.js\", not be empty"
        ));
    }
    let module_file = format!("{module}.js");
    let mut out = Vec::with_capacity(list.len());
