        let empty = Map::new();
        let fields = file.as_object().unwrap_or(&empty);
        let path = string(fields, "path", &format!("files[{index}].path"))?;
        let name = string(fields, "name", &format!("files[{index}].name"))?;
        let Some(size) = fields.get("size").and_then(Value::as_u64) else {
