            }
        } else {
            let folder = ["fonts", "assets"]
                .into_iter()
                .find(|f| path.strip_prefix(f).is_some_and(|n| n.starts_with('/')));
            let legal = folder.is_some_and(|f| is_legal(&path[f.len() + 1..]));
