        Some(1) => {}
        Some(n) if n > 1 => {
            return Err(format!(
                "the package is format {n}; this Frame Job reads format 1 — a newer Frame Job wrote it"
            ))
        }
        _ => {
            return Err(format!(
                "fjgraphic must be 1, not {}",
                shown(object.get("fjgraphic"))
            ))
        }
    }
    let module = string(object, "module", "module")?;
    check_name(&module)?;
    let title = string(object, "title", "title")?;
    let category = string(object, "category", "category")?;
    let description = match object.get("description") {
        Some(Value::String(text)) => Value::String(text.clone()),
        Some(Value::Null) => Value::Null,
        other => {
            return Err(format!(
                "description must be a string or null, not {}",
                shown(other)
            ))
        }
    };
    let app_version = string(object, "app_version", "app_version")?;
    let files = files(object, &module)?;
    let mut out = Map::new();
    out.insert("fjgraphic".to_string(), Value::from(1));
    out.insert("module".to_string(), Value::String(module.clone()));
    out.insert("title".to_string(), Value::String(title));
    out.insert("category".to_string(), Value::String(category));
    out.insert("description".to_string(), description);
    out.insert("app_version".to_string(), Value::String(app_version));
    Ok((out, module, files))
}

/// U+0000–U+001F and U+007F–U+009F.
fn is_control(c: char) -> bool {
    matches!(c as u32, 0..=0x1F | 0x7F..=0x9F)
