fn items(manifest: &Value, files: &[(&str, &str, &[u8])]) -> Vec<Item> {
    let mut all = vec![item("manifest.json", manifest.to_string().as_bytes())];
    all.extend(files.iter().map(|(path, _, bytes)| item(path, bytes)));
    all
